public class Main {
    public static void main(String[] args) {
        int batas = 3;
        Cek c = x -> x > batas;
        batas = 5;
        System.out.println(c.periksa(4));
    }
}

interface Cek {
    boolean periksa(int x);
}

public class Main {
    public static void main(String[] args) {
        Hitung h = (a, b) -> {
            if (a > b) {
                return a - b;
            }
            return b - a;
        };
        System.out.println(h.jalankan(4, 9));
    }
}

@FunctionalInterface
interface Hitung {
    int jalankan(int a, int b);
}

public class Main {
    public static void main(String[] args) {
        Ubah u = x -> {
            int hasil = x + 1;
        };
        System.out.println(u.ubah(1));
    }
}

interface Ubah {
    int ubah(int x);
}

